=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v (N = 8). It extends irq_ctrl_idle_tb.sv:
// the same interface, clocking and verdict line, plus stimulus that exercises
// detection (level and edge), W1C clearing, acknowledge (in and out of range),
// fixed priority, enable masking, detection-wins-over-clear, reset with live
// state, and seeded random traffic. Every check compares against a cycle
// reference model kept in this file.
`timescale 1ns / 1ps
module irq_ctrl_cov_tb;
    localparam int N = 8;
    localparam logic [N-1:0] ONE = {{(N-1){1'b0}}, 1'b1};
    localparam logic [1:0] A_ENABLE = 2'd0, A_MODE = 2'd1, A_PENDING = 2'd2, A_CLAIM = 2'd3;

    logic         clk = 1'b0;
    logic         rst_n = 1'b0;
    logic [N-1:0] src = '0;
    logic         we = 1'b0;
    logic [1:0]   addr = 2'd0;
    logic [31:0]  wdata = 32'd0;
    logic [31:0]  rdata;
    logic         irq;
    logic [4:0]   irq_id;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    // Reference model state.
    logic [N-1:0] m_enable = '0;
    logic [N-1:0] m_mode = '0;
    logic [N-1:0] m_pending = '0;
    logic [N-1:0] m_src_q = '0;
    logic [31:0]  rnd = 32'h1D87_2B41;

    irq_ctrl #(.N(N)) dut (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
                           .rdata(rdata), .irq(irq), .irq_id(irq_id));
    always #5 clk = ~clk;

    function automatic logic [31:0] next_rand(input logic [31:0] x);
        logic [31:0] y;
        y = x ^ (x << 13);
        y = y ^ (y >> 17);
        y = y ^ (y << 5);
        return y;
    endfunction

    function automatic logic [4:0] exp_id(input logic [N-1:0] act);
        logic [4:0] id;
        id = 5'd0;
        for (int j = N - 1; j >= 0; j--)
            if (act[j]) id = 5'(j);
        return id;
    endfunction

    function automatic logic [31:0] exp_rdata(input logic [1:0] a);
        logic [N-1:0] act;
        logic [31:0]  r;
        act = m_pending & m_enable;
        r = 32'd0;
        case (a)
            A_ENABLE:  r[N-1:0] = m_enable;
            A_MODE:    r[N-1:0] = m_mode;
            A_PENDING: r[N-1:0] = m_pending;
            default: begin
                r[31]  = |act;
                r[4:0] = exp_id(act);
            end
        endcase
        return r;
    endfunction

    // One clock edge: compute the model's next state from the current inputs,
    // wait for the edge, settle, then update the model.
    task automatic step();
        logic [N-1:0] n_enable, n_mode, n_pending, n_src_q, det, clr;
        if (!rst_n) begin
            n_enable  = '0;
            n_mode    = '0;
            n_pending = '0;
            n_src_q   = '0;
        end else begin
            det = (m_mode & src & ~m_src_q) | (~m_mode & src);
            clr = '0;
            if (we && addr == A_PENDING) clr = wdata[N-1:0];
            if (we && addr == A_CLAIM && {27'd0, wdata[4:0]} < 32'(N)) clr = clr | (ONE << wdata[4:0]);
            n_pending = det | (m_pending & ~clr);
            n_src_q   = src;
            n_enable  = (we && addr == A_ENABLE) ? wdata[N-1:0] : m_enable;
            n_mode    = (we && addr == A_MODE) ? wdata[N-1:0] : m_mode;
        end
        @(posedge clk);
        #1;
        m_enable  = n_enable;
        m_mode    = n_mode;
        m_pending = n_pending;
        m_src_q   = n_src_q;
    endtask

    task automatic idle(input int n);
        repeat (n) step();
    endtask

    task automatic write_reg(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1;
        addr = a;
        wdata = d;
        step();
        we = 1'b0;
        wdata = 32'd0;
    endtask

    task automatic check_out();
        logic [N-1:0] act;
        act = m_pending & m_enable;
        checks++;
        if (irq !== (|act) || irq_id !== exp_id(act)) begin
            errors++;
            $display("ERROR t=%0t irq=%b irq_id=%0d expected irq=%b irq_id=%0d",
                     $time, irq, irq_id, |act, exp_id(act));
        end
    endtask

    task automatic check_reg(input logic [1:0] a);
        logic [31:0] e;
        addr = a;
        #1;
        e = exp_rdata(a);
        checks++;
        if (rdata !== e) begin
            errors++;
            $display("ERROR t=%0t addr=%0d rdata=%h expected=%h", $time, a, rdata, e);
        end
    endtask

    task automatic check_all();
        check_out();
        check_reg(A_ENABLE);
        check_reg(A_MODE);
        check_reg(A_PENDING);
        check_reg(A_CLAIM);
    endtask

    initial begin : main
        int k;
        logic [31:0] r;

        // 1. Reset from idle.
        rst_n = 1'b0;
        idle(3);
        rst_n = 1'b1;
        step();
        check_all();

        // 2. Register access: every wdata bit both ways, both write branches.
        write_reg(A_ENABLE, 32'hFFFF_FFFF); check_all();
        write_reg(A_ENABLE, 32'h0000_0000); check_all();
        write_reg(A_MODE,   32'hFFFF_FFFF); check_all();
        write_reg(A_MODE,   32'h0000_0000); check_all();
        write_reg(A_ENABLE, 32'h0000_00A5); check_all();
        write_reg(A_MODE,   32'h0000_005A); check_all();
        write_reg(A_ENABLE, 32'h0000_005A); check_all();
        write_reg(A_MODE,   32'h0000_00A5); check_all();
        write_reg(A_PENDING, 32'hFFFF_FFFF); check_all();  // nothing pending to clear
        write_reg(A_CLAIM,   32'hFFFF_FFFF); check_all();  // id 31: out of range, ignored

        // 3. Level mode, one source at a time: detect, sticky, W1C.
        write_reg(A_MODE,   32'h0000_0000);
        write_reg(A_ENABLE, 32'h0000_00FF);
        for (k = 0; k < N; k++) begin
            src = ONE << k;
            step(); check_all();
            src = '0;
            step(); check_all();
            write_reg(A_PENDING, 32'd1 << k); check_all();
        end

        // 4. Priority and acknowledge: all pending, claimed lowest first.
        src = {N{1'b1}};
        step(); check_all();
        src = '0;
        step(); check_all();
        write_reg(A_CLAIM, 32'h0000_001F); check_all();  // out of range
        write_reg(A_CLAIM, 32'h0000_0008); check_all();  // id N: out of range
        for (k = 0; k < N; k++) begin
            write_reg(A_CLAIM, 32'hFFFF_FFE0 | 32'(k)); check_all();  // upper bits ignored
        end

        // 5. Enable masking: irq_id follows the enabled source, then irq drops.
        src = {N{1'b1}};
        step();
        src = '0;
        step(); check_all();
        for (k = 0; k < N; k++) begin
            write_reg(A_ENABLE, 32'd1 << (N - 1 - k)); check_all();
        end
        write_reg(A_ENABLE, 32'h0000_0000); check_all();
        write_reg(A_ENABLE, 32'h0000_00FF); check_all();
        write_reg(A_PENDING, 32'h0000_00FF); check_all();

        // 6. Edge mode: detected once on a rising edge, not while held high.
        write_reg(A_MODE, 32'h0000_00FF);
        src = 8'h0F; step(); check_all();
        idle(2); check_all();
        write_reg(A_PENDING, 32'h0000_000F); check_all();
        idle(2); check_all();
        src = 8'hF0; step(); check_all();
        src = 8'hFF; step(); check_all();
        src = 8'h00; step(); check_all();
        write_reg(A_PENDING, 32'h0000_00FF); check_all();

        // 7. A detection wins over a clear at the same edge.
        write_reg(A_MODE, 32'h0000_0000);
        src = 8'h04; step(); check_all();
        write_reg(A_PENDING, 32'h0000_0004); check_all();  // level still high: stays pending
        write_reg(A_CLAIM,   32'h0000_0002); check_all();  // acknowledge loses too
        src = '0;
        step(); check_all();
        write_reg(A_CLAIM,   32'h0000_0002); check_all();  // now cleared
        write_reg(A_MODE, 32'h0000_0020);
        we = 1'b1; addr = A_PENDING; wdata = 32'h0000_0020; src = 8'h20;
        step();
        we = 1'b0; wdata = 32'd0;
        check_all();                                        // edge beats W1C
        src = '0;
        write_reg(A_PENDING, 32'h0000_0020); check_all();

        // 8. Reset with live state.
        write_reg(A_ENABLE, 32'h0000_00FF);
        write_reg(A_MODE,   32'h0000_0033);
        src = 8'hFF;
        step(); check_all();
        rst_n = 1'b0;
        step(); check_all();
        step(); check_all();
        src = '0;
        rst_n = 1'b1;
        step(); check_all();

        // 9. Seeded random traffic against the model.
        write_reg(A_ENABLE, 32'h0000_00FF);
        for (k = 0; k < 600; k++) begin
            rnd = next_rand(rnd);
            r = rnd;
            if (r[12]) src = r[N-1:0];
            we = (r[9:8] == 2'b00);
            addr = r[11:10];
            rnd = next_rand(rnd);
            wdata = we ? rnd : 32'd0;
            step();
            we = 1'b0;
            wdata = 32'd0;
            check_all();
        end

        src = '0; we = 1'b0; addr = 2'd0; wdata = 32'd0;
        step();
        check_all();

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
